#include "pixcake/gl/gl.hpp"

#include <utility>

namespace pixcake::gl {
namespace {
class NullContext final : public detail::ContextImpl {
 public:
  bool make_current(std::string& error) override { error = last_error_; return false; }
  void done_current() override {}
  std::string last_error() const override { return last_error_; }
 private:
  std::string last_error_ = "no GPU backend is registered";
};
class NullShader final : public detail::ShaderImpl { public: bool compile(ShaderStage, std::string_view, std::string& e) override { e = "no GPU backend is registered"; return false; } };
class NullProgram final : public detail::ProgramImpl { public: bool link(const detail::ShaderImpl&, const detail::ShaderImpl&, std::string& e) override { e="no GPU backend is registered"; return false; } bool use(std::string& e) override { e="no GPU backend is registered"; return false; } bool set_float(std::string_view,float,std::string&e) override {e="no GPU backend is registered";return false;} bool set_int(std::string_view,std::int32_t,std::string&e) override {e="no GPU backend is registered";return false;} bool set_vec4(std::string_view,const std::array<float,4>&,std::string&e) override {e="no GPU backend is registered";return false;} bool set_mat4(std::string_view,const std::array<float,16>&,std::string&e) override {e="no GPU backend is registered";return false;} bool set_texture_unit(std::string_view,std::uint32_t,std::string&e) override {e="no GPU backend is registered";return false;} };
class NullBuffer final : public detail::BufferImpl { public: bool allocate(std::size_t,const void*,std::string&e) override {e="no GPU backend is registered";return false;} bool write(std::size_t,std::size_t,const void*,std::string&e) override {e="no GPU backend is registered";return false;} };
class NullVertexArray final : public detail::VertexArrayImpl { public: bool bind(std::string&e) override {e="no GPU backend is registered";return false;} bool enable_attribute(std::uint32_t,std::int32_t,std::uint32_t,std::size_t,std::string&e) override {e="no GPU backend is registered";return false;} };
class NullTexture final : public detail::Texture2DImpl { public: bool allocate(std::uint32_t,std::uint32_t,PixelFormat,std::string&e) override {e="no GPU backend is registered";return false;} bool upload(const ImageView&,std::string&e) override {e="no GPU backend is registered";return false;} bool bind(std::uint32_t,std::string&e) override {e="no GPU backend is registered";return false;} };
class NullFramebuffer final : public detail::FramebufferImpl { public: bool attach_color(const detail::Texture2DImpl&,std::string&e) override {e="no GPU backend is registered";return false;} bool complete(std::string&e) override {e="no GPU backend is registered";return false;} bool bind(std::string&e) override {e="no GPU backend is registered";return false;} };
class NullFence final : public detail::FenceImpl { public: bool insert(std::string&e) override {e="no GPU backend is registered";return false;} bool wait(std::uint64_t,std::string&e) override {e="no GPU backend is registered";return false;} };
}  // namespace

Context::Context() : impl_(std::make_shared<NullContext>()) {} Context::Context(std::shared_ptr<detail::ContextImpl> p):impl_(std::move(p)){} Context Context::create(){return Context();} bool Context::makeCurrent(){std::string e;return impl_&&impl_->make_current(e);} void Context::doneCurrent(){if(impl_)impl_->done_current();} std::string Context::lastError()const{return impl_?impl_->last_error():"context is empty";} bool Context::valid()const{return impl_!=nullptr;}
Shader::Shader():impl_(std::make_shared<NullShader>()){} Shader::Shader(std::shared_ptr<detail::ShaderImpl> p):impl_(std::move(p)){} Shader Shader::create(){return Shader();} bool Shader::compile(ShaderStage s,std::string_view v,std::string&e){return impl_&&impl_->compile(s,v,e);} bool Shader::valid()const{return impl_!=nullptr;} const detail::ShaderImpl* Shader::implementation()const{return impl_.get();}
Program::Program():impl_(std::make_shared<NullProgram>()){} Program::Program(std::shared_ptr<detail::ProgramImpl> p):impl_(std::move(p)){} Program Program::create(){return Program();} bool Program::link(const Shader&a,const Shader&b,std::string&e){return impl_&&a.implementation()&&b.implementation()&&impl_->link(*a.implementation(),*b.implementation(),e);} bool Program::use(std::string&e){return impl_&&impl_->use(e);} bool Program::setFloat(std::string_view n,float v,std::string&e){return impl_&&impl_->set_float(n,v,e);} bool Program::setInt(std::string_view n,std::int32_t v,std::string&e){return impl_&&impl_->set_int(n,v,e);} bool Program::setVec4(std::string_view n,const std::array<float,4>&v,std::string&e){return impl_&&impl_->set_vec4(n,v,e);} bool Program::setMat4(std::string_view n,const std::array<float,16>&v,std::string&e){return impl_&&impl_->set_mat4(n,v,e);} bool Program::setTextureUnit(std::string_view n,std::uint32_t v,std::string&e){return impl_&&impl_->set_texture_unit(n,v,e);} bool Program::valid()const{return impl_!=nullptr;}
Buffer::Buffer():impl_(std::make_shared<NullBuffer>()){} Buffer::Buffer(std::shared_ptr<detail::BufferImpl>p):impl_(std::move(p)){} Buffer Buffer::create(){return Buffer();} bool Buffer::allocate(std::size_t n,const void*d,std::string&e){return impl_&&impl_->allocate(n,d,e);} bool Buffer::write(std::size_t o,std::size_t n,const void*d,std::string&e){return impl_&&impl_->write(o,n,d,e);} bool Buffer::valid()const{return impl_!=nullptr;}
VertexArray::VertexArray():impl_(std::make_shared<NullVertexArray>()){} VertexArray::VertexArray(std::shared_ptr<detail::VertexArrayImpl>p):impl_(std::move(p)){} VertexArray VertexArray::create(){return VertexArray();} bool VertexArray::bind(std::string&e){return impl_&&impl_->bind(e);} bool VertexArray::enableAttribute(std::uint32_t i,std::int32_t c,std::uint32_t s,std::size_t o,std::string&e){return impl_&&impl_->enable_attribute(i,c,s,o,e);} bool VertexArray::valid()const{return impl_!=nullptr;}
Texture2D::Texture2D():impl_(std::make_shared<NullTexture>()){} Texture2D::Texture2D(std::shared_ptr<detail::Texture2DImpl>p):impl_(std::move(p)){} Texture2D Texture2D::create(){return Texture2D();} bool Texture2D::allocate(std::uint32_t w,std::uint32_t h,PixelFormat f,std::string&e){return impl_&&impl_->allocate(w,h,f,e);} bool Texture2D::upload(const ImageView&i,std::string&e){return impl_&&impl_->upload(i,e);} bool Texture2D::bind(std::uint32_t u,std::string&e){return impl_&&impl_->bind(u,e);} bool Texture2D::valid()const{return impl_!=nullptr;} const detail::Texture2DImpl* Texture2D::implementation()const{return impl_.get();}
Framebuffer::Framebuffer():impl_(std::make_shared<NullFramebuffer>()){} Framebuffer::Framebuffer(std::shared_ptr<detail::FramebufferImpl>p):impl_(std::move(p)){} Framebuffer Framebuffer::create(){return Framebuffer();} bool Framebuffer::attachColor(const Texture2D&t,std::string&e){return impl_&&t.implementation()&&impl_->attach_color(*t.implementation(),e);} bool Framebuffer::complete(std::string&e){return impl_&&impl_->complete(e);} bool Framebuffer::bind(std::string&e){return impl_&&impl_->bind(e);} bool Framebuffer::valid()const{return impl_!=nullptr;}
Fence::Fence():impl_(std::make_shared<NullFence>()){} Fence::Fence(std::shared_ptr<detail::FenceImpl>p):impl_(std::move(p)){} Fence Fence::create(){return Fence();} bool Fence::insert(std::string&e){return impl_&&impl_->insert(e);} bool Fence::wait(std::uint64_t n,std::string&e){return impl_&&impl_->wait(n,e);} bool Fence::valid()const{return impl_!=nullptr;}
} // namespace pixcake::gl
